<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElCheckbox, ElDatePicker, ElDialog, ElInput, ElInputNumber, ElMessage, ElOption, ElSelect, ElTag } from 'element-plus'
import { ArrowLeft, ClipboardList, Copy, Search } from 'lucide-vue-next'
import ListPagination from '@/components/commerce/ListPagination.vue'
import OrderProductSummary from '@/components/commerce/OrderProductSummary.vue'
import ListStatusTabs from '@/components/commerce/ListStatusTabs.vue'
import AdvancedListFilterBar from '@/components/commerce/AdvancedListFilterBar.vue'
import { useOnboardingStore } from '@/stores/onboarding'
import { money, useCommerceStore } from '@/stores/commerce'
import { salePrice, useProductsStore } from '@/stores/products'
import DemoImage from '@/components/commerce/DemoImage.vue'
import { linkKnownDemoOrders } from './orderProductDemoLinks'

type Status = 'pending_pay' | 'pending_ship' | 'shipped' | 'received' | 'completed' | 'cancelled'
type Item = { id: string; productId?: string; cover?: string; name: string; sku: string; orderCode?: string; brand?: string; model?: string; remark?: string; unit: string; qty: number; price: number; shipped: number }
type Shipment = { company: string; tracking: string; note: string; time: string; lines: { itemId: string; qty: number }[] }
type Order = { id: string; park: string; customer: string; created: string; status: Status; address: string; buyerNote?: string; payDueAt?: string; cancelledAt?: string; settledAt?: string; autoReceiveAt?: string; receiver?: string; phone?: string; freight?: number; paidAmount?: number; paidAt?: string; receivedAt?: string; completedAt?: string; settleAmount?: number; commissionRate?: number; settleStatus?: string; items: Item[]; shipments: Shipment[] }
const ob = useOnboardingStore()
const router=useRouter(), route=useRoute(), products=useProductsStore(), commerce=useCommerceStore()
const labels: Record<Status, string> = { pending_pay: '待支付', pending_ship: '待发货', shipped: '已发货', received: '已签收', completed: '已完成', cancelled: '已取消' }
const tabs = [['all','全部'], ['pending_pay','待支付'], ['pending_ship','待发货'], ['partial','部分发货'], ['shipped','已发货'], ['received','已签收'], ['completed','已完成'], ['cancelled','已取消']]
const baseSample = (): Order[] => [
  { id:'JC-DEMO-001',park:'上海临港新片区智能制造产业园',customer:'园区企业客户（演示）',receiver:'张敏',created:'2026/10/20 10:30',status:'pending_ship',address:'上海市浦东新区临港新片区（演示地址）',items:[{id:'1',name:'工业防护手套',sku:'耐磨款 · M 码',unit:'双',qty:100,price:18.5,shipped:20},{id:'2',name:'安全防护眼镜',sku:'透明款',unit:'副',qty:30,price:25,shipped:0}],shipments:[{company:'顺丰速运',tracking:'DEMO2026102001',note:'',time:'2026/10/21 10:00',lines:[{itemId:'1',qty:20}]}] },
  { id:'JC-DEMO-002',park:'苏州工业园区企业服务中心',customer:'园区企业客户（演示）',receiver:'李娜',created:'2026/10/19 14:20',status:'pending_pay',address:'江苏省苏州市工业园区（演示地址）',items:[{id:'3',name:'工业安全帽',sku:'白色 · 标准款',unit:'顶',qty:50,price:48,shipped:0}],shipments:[] },
  { id:'JC-DEMO-003',park:'上海临港新片区智能制造产业园',customer:'园区企业客户（演示）',receiver:'王磊',created:'2026/10/15 09:15',status:'shipped',address:'上海市浦东新区临港新片区（演示地址）',items:[{id:'4',name:'防护口罩',sku:'独立包装',unit:'盒',qty:20,price:32,shipped:20}],shipments:[{company:'中通快递',tracking:'DEMO2026101601',note:'',time:'2026/10/16 15:00',lines:[{itemId:'4',qty:20}]}] },
]
const sample = (): Order[] => {
 const statuses: Status[]=['pending_pay','pending_ship','pending_ship','shipped','received','completed','cancelled','pending_pay','pending_ship']
 const receivers=['陈晨','刘洋','赵静','孙伟','周宁','徐洁','林峰','杨帆','何静']
 const names=['工业安全帽','防护眼镜','绝缘手套','充电电钻','劳保口罩','安全警示牌','工业防护手套','活动扳手','防护面罩']
 return linkKnownDemoOrders([...baseSample(),...statuses.map((status,i):Order=>{const qty=20+i*5, shipped=['shipped','received','completed'].includes(status)?qty:0; return {id:`JC-DEMO-${String(i+4).padStart(3,'0')}`,park:i%2?'苏州工业园区企业服务中心':'上海临港新片区智能制造产业园',customer:`园区企业客户 ${i+1}（演示）`,receiver:receivers[i],phone:'13800000000',buyerNote:i===1?'请在工作日送货':'',address:i%2?'江苏省苏州市工业园区（演示地址）':'上海市浦东新区临港新片区（演示地址）',created:`2026/10/${String(14-i).padStart(2,'0')} 10:30`,status,paidAt:status==='pending_pay'||status==='cancelled'?'':'2026/10/15 11:00',receivedAt:['received','completed'].includes(status)?'2026/10/20 11:00':'',completedAt:status==='completed'?'2026/10/27 11:00':'',settleStatus:status==='completed'?'已结算':'待结算',settledAt:status==='completed'?'2026/10/27 12:00':'',settleAmount:['completed','received'].includes(status)?(25+i*10)*qty*.9:undefined,commissionRate:10,items:[{id:`extra-${i}`,name:names[i]!,sku:`SKU-${1001+i}`,orderCode:`ORDER-${1001+i}`,brand:i%2?'得力':'3M',model:`型号 ${i+1}`,unit:'件',qty,price:25+i*10,shipped}],shipments:shipped?[{company:'顺丰速运',tracking:`DEMO100${i}`,note:'',time:'2026/10/17 09:00',lines:[{itemId:`extra-${i}`,qty}]}]:[]}})].map(o=>({...o,paidAmount:o.status==='pending_pay'||o.status==='cancelled'?0:o.items.reduce((sum,item)=>sum+item.price*item.qty,0)+(o.freight||0)})), products.products)
}
const key = computed(() => `gysd-procurement-orders-${ob.activeId}`)
function read(): Order[] { try {
 const saved = localStorage.getItem(key.value)
 if (!saved) return sample()
 const data: Order[] = JSON.parse(saved)
 if (!Array.isArray(data)) return sample()
 const migrationKey = `${key.value}-examples-v2`
 if (!localStorage.getItem(migrationKey) && data.some(o=>o.id.startsWith('JC-DEMO-'))) {
   const ids=new Set(data.map(o=>o.id)); data.push(...sample().filter(o=>!ids.has(o.id)))
   localStorage.setItem(key.value, JSON.stringify(data)); localStorage.setItem(migrationKey,'1')
 }
 const examples = new Map(sample().map(o => [o.id, o]))
 for (const o of data) {
   const example = examples.get(o.id)
   if (!example) continue
   if (!o.receiver || /^收货人\d+（演示）$/.test(o.receiver)) o.receiver=example.receiver
   if (o.paidAmount == null) o.paidAmount=o.status==='pending_pay'||(o.status==='cancelled'&&!o.paidAt)?0:o.items.reduce((sum,item)=>sum+item.price*item.qty,0)+(o.freight||0)
 }
 const linked = linkKnownDemoOrders(data, products.products)
 if (JSON.stringify(linked)!==JSON.stringify(data)) localStorage.setItem(key.value, JSON.stringify(linked))
 return linked
 } catch { return sample() } }
const orders = ref<Order[]>(read()); watch(key, () => { orders.value = read(); selected.value = ''; shipping.value=false; if(route.query.order||route.query.fromProduct||route.query.productId)router.replace({path:'/procurement/orders'}) }, { flush:'sync' }); watch(orders, v => localStorage.setItem(key.value, JSON.stringify(v)), { deep:true, flush:'sync' })
const showEmpty = ref(false)
function fillDemo(){ const known=new Set(orders.value.map(o=>o.id)); orders.value.push(...sample().filter(o=>!known.has(o.id))); const product=products.products.find(p=>p.id==='JC-PRODUCT-001' && (p.status==='on_sale'||p.status==='price_review') && p.parkIds.some(id=>!!p.parks[id] && (p.parkStatuses?.[id]||'on_sale')==='on_sale' && !!commerce.joinedParks.find(park=>park.id===id))); if(product && !known.has('JC-DEMO-LINKED-001')){const parkId=product.parkIds.find(id=>!!product.parks[id] && (product.parkStatuses?.[id]||'on_sale')==='on_sale' && !!commerce.joinedParks.find(park=>park.id===id))!;const supply=product.parks[parkId];orders.value.push({id:'JC-DEMO-LINKED-001',park:commerce.joinedParks.find(park=>park.id===parkId)!.name,customer:'园区企业客户（演示）',receiver:'演示收货人',created:new Date().toLocaleString('zh-CN',{hour12:false}),status:'pending_ship',address:'演示收货地址',paidAmount:priceForSample(supply),items:[{id:'demo-linked-item-001',productId:product.id,cover:product.cover,name:product.name,sku:product.sku,unit:product.unit||'件',qty:1,price:priceForSample(supply),shipped:0}],shipments:[]})} showEmpty.value=false; tab.value='all'; reset(); ElMessage.success('演示订单已补充') }
function priceForSample(supply:Parameters<typeof salePrice>[0]) { return Math.round(salePrice(supply)*(1+supply.tax/100)*100)/100 }
const advancedFilters = ref(false)
const filter = reactive({park:'', id:'', product:'', code:'', from:'', to:''}); const applied = reactive({...filter}); const tab = ref('all'); const page = ref(1); const selected = ref(typeof route.query.order==='string'?route.query.order:''); const order = computed(() => orders.value.find(o => o.id === selected.value))
watch(()=>route.query.order, value=>{selected.value=typeof value==='string'?value:''})
function openDetails(o:Order) { router.push({path:'/procurement/orders',query:{...route.query,order:o.id}}) }
function backToList() { const query={...route.query};delete query.order;router.push({path:'/procurement/orders',query}) }
const productScope = computed(()=>typeof route.query.productId==='string'?route.query.productId:'')
const originProduct = computed(()=>typeof route.query.fromProduct==='string'?route.query.fromProduct:'')
const originDetail = computed(()=>route.query.origin==='detail')
const scopeProduct = computed(()=>products.products.find(p=>p.id===productScope.value))
function returnToProduct() { if(!originProduct.value)return;const fromOrder=typeof route.query.backOrder==='string'?route.query.backOrder:'';const orderReturn=typeof route.query.backReturn==='string'?route.query.backReturn:'';router.push(originDetail.value?{name:'product-detail',params:{id:originProduct.value},query:{...(fromOrder?{fromOrder}:{}),...(orderReturn?{orderReturn}:{})}}:{path:'/product',query:{restoreList:'1'}}) }
function clearProductScope() {const query={...route.query};delete query.productId;showEmpty.value=false;tab.value='all';reset();router.replace({path:'/procurement/orders',query})}
function restoreProductScope() {if(!originProduct.value)return;showEmpty.value=false;tab.value='all';reset();router.replace({path:'/procurement/orders',query:{...route.query,productId:originProduct.value}})}
function linkedProduct(item:Item) { return item.productId ? products.products.find(p=>p.id===item.productId) : undefined }
function openProduct(item:Item) { const p=linkedProduct(item);if(p)router.push({name:'product-detail',params:{id:p.id},query:order.value?{fromOrder:order.value.id,orderReturn:route.fullPath}:{}}) }
const isPartial = (o: Order) => o.status === 'pending_ship' && o.items.some(i => i.shipped > 0)
const filtered = computed(() => (showEmpty.value ? [] : orders.value).filter(o => (!productScope.value || o.items.some(i=>i.productId===productScope.value)) && (!applied.park || o.park === applied.park) && (!applied.id || [o.id,o.receiver||'',o.phone||''].some(x=>x.toLowerCase().includes(applied.id.trim().toLowerCase()))) && (!applied.product || o.items.some(i => (i.name+i.sku).includes(applied.product.trim()))) && (!applied.code || o.items.some(i=>[i.sku,i.orderCode || ''].some(code=>code.toLowerCase().includes(applied.code.trim().toLowerCase())))) && (!applied.from || o.created.slice(0,10).replaceAll('/','-') >= applied.from) && (!applied.to || o.created.slice(0,10).replaceAll('/','-') <= applied.to)))
const count = (s:string) => filtered.value.filter(o => s === 'all' || (s === 'partial' ? isPartial(o) : o.status === s && (s !== 'pending_ship' || !isPartial(o)))).length
const matched = computed(() => filtered.value.filter(o => tab.value === 'all' || (tab.value === 'partial' ? isPartial(o) : o.status === tab.value && (tab.value !== 'pending_ship' || !isPartial(o)))))
const rows = computed(() => matched.value.slice((page.value-1)*20,page.value*20)); const amount = (o:Order) => o.items.reduce((s,i)=>s+i.price*i.qty,0)
const quantityByUnit = (o:Order) => { const totals = new Map<string, number>(); for (const item of o.items) totals.set(item.unit || '件', (totals.get(item.unit || '件') || 0) + item.qty); return [...totals].map(([unit, qty]) => `${qty} ${unit}`).join('、') || '—' }
const paidText = (o:Order) => typeof o.paidAmount==='number' && Number.isFinite(o.paidAmount) ? money(o.paidAmount) : o.status==='pending_pay' ? money(0) : '—'
function query() { Object.assign(applied, filter); page.value=1 }
function reset() { Object.assign(filter,{park:'',id:'',product:'',code:'',from:'',to:''}); query() }
const contactOpen = ref(false)
async function copyText(value:string){try{await navigator.clipboard.writeText(value);ElMessage.success('已复制')}catch{ElMessage.warning('复制失败，请手动选择内容')}}
const shipping = ref(false), shippingId=ref(''), shipSelected=ref<string[]>([]); const shippingOrder=computed(()=>orders.value.find(o=>o.id===shippingId.value)); const shipForm = reactive({ company:'', tracking:'', note:'', self:false, quantities:{} as Record<string,number> })
function fillShipping(){if(shippingOrder.value){shipSelected.value=shippingOrder.value.items.filter(item=>item.qty>item.shipped).map(item=>item.id);for(const item of shippingOrder.value.items) shipForm.quantities[item.id]=item.qty-item.shipped;shipForm.company='顺丰速运';shipForm.tracking='DEMO20261028001';ElMessage.success('已填入演示发货信息')}}
function simulate(o:Order){if(o.status==='pending_pay'){o.status='pending_ship';o.paidAmount=amount(o)+(o.freight||0);o.paidAt=new Date().toLocaleString('zh-CN',{hour12:false})}else if(o.status==='shipped'){o.status='received';o.receivedAt=new Date().toLocaleString('zh-CN',{hour12:false});o.settleStatus='待结算'}ElMessage.success('演示状态已更新')}
const stage = (o:Order) => o.status==='pending_pay'?0:o.status==='pending_ship'?1:o.status==='shipped'?2:3
function openShipping(o:Order) { shippingId.value=o.id; shipSelected.value=o.items.filter(i=>i.qty>i.shipped).map(i=>i.id); Object.assign(shipForm,{company:'', tracking:'', note:'', self:false, quantities:Object.fromEntries(o.items.map(i=>[i.id,Math.max(0,i.qty-i.shipped)]))}); shipping.value=true }
function submitShipping() {
 const o=shippingOrder.value; if (!o || o.status !== 'pending_ship') { ElMessage.warning('订单状态已变更，请刷新后重试');return }
 const lines=o.items.filter(i=>shipSelected.value.includes(i.id)).map(i=>({itemId:i.id,qty:Number(shipForm.quantities[i.id] || 0)}))
 if (!lines.length || lines.some(l=>!Number.isInteger(l.qty) || l.qty<=0 || l.qty > (o.items.find(i=>i.id===l.itemId)!.qty-o.items.find(i=>i.id===l.itemId)!.shipped))) { ElMessage.error('请填写有效的发货数量，且不超过待发数量'); return }
 if (!shipForm.self && (!shipForm.company.trim() || !shipForm.tracking.trim())) { ElMessage.error('请填写物流公司和物流单号'); return }
 if (shipForm.self && !shipForm.note.trim()) { ElMessage.error('请填写自送说明'); return }
 o.shipments.push({company:shipForm.self?'自送':shipForm.company.trim(),tracking:shipForm.self?'':shipForm.tracking.trim(),note:shipForm.note.trim(),time:new Date().toLocaleString('zh-CN',{hour12:false}),lines})
 for(const l of lines) o.items.find(i=>i.id===l.itemId)!.shipped += l.qty
 if(o.items.every(i=>i.shipped===i.qty)) o.status='shipped'
 shipping.value=false; ElMessage.success('发货信息已记录')
}
const shipmentIndex=ref<number|null>(null)
const selectedShipment=computed(()=>shipmentIndex.value===null?undefined:order.value?.shipments[shipmentIndex.value])
</script>
<template>
 <div class="biz-page procurement-orders">
  <template v-if="!selected">
   <header class="biz-head"><span class="heading-icon"><ClipboardList :size="24" /></span><h1>订单管理</h1><div class="head-actions"><ElButton @click="showEmpty=!showEmpty; page=1">{{ showEmpty ? '返回订单列表' : '查看空状态' }}</ElButton><ElButton type="primary" plain @click="fillDemo">演示填入</ElButton></div></header>
   <div v-if="originProduct" class="product-order-context"><div class="context-main"><ElButton text type="primary" @click="returnToProduct"><ArrowLeft :size="15"/>返回{{originDetail ? '商品详情' : '商品管理'}}</ElButton><span class="context-divider"></span><span v-if="productScope">当前查看商品 <strong>{{scopeProduct?.name || '（商品已不可用）'}}</strong> 的订单</span><span v-else>当前查看全部订单</span></div><ElButton v-if="productScope" text type="primary" @click="clearProductScope">查看全部订单</ElButton><ElButton v-else text type="primary" @click="restoreProductScope">只看此商品订单</ElButton></div>
   <div class="order-sticky list-sticky">
    <AdvancedListFilterBar v-model:expanded="advancedFilters" :advanced-count="[filter.code, filter.from || filter.to].filter(Boolean).length" @query="query" @reset="reset">
      <template #first><ElSelect v-model="filter.park" placeholder="全部已加入园区" clearable><ElOption v-for="p in [...new Set(orders.map(o=>o.park))]" :key="p" :label="p" :value="p" /></ElSelect></template>
      <template #second><ElInput v-model="filter.product" placeholder="商品名称" clearable @keyup.enter="query"><template #prefix><Search :size="14" /></template></ElInput></template>
      <template #third><ElInput v-model="filter.id" placeholder="订单号 / 收货人 / 手机号" clearable @keyup.enter="query"><template #prefix><Search :size="14" /></template></ElInput></template>
      <template #advanced-first><ElInput v-model="filter.code" placeholder="订货编码 / SKU" clearable @keyup.enter="query" /></template>
      <template #advanced-date><div class="order-date"><span>下单时间</span><ElDatePicker v-model="filter.from" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" placeholder="开始日期" popper-class="biz-date-popper" :editable="false" /><b>至</b><ElDatePicker v-model="filter.to" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" placeholder="结束日期" popper-class="biz-date-popper" :editable="false" /></div></template>
    </AdvancedListFilterBar>
    <ListStatusTabs :model-value="tab" :items="tabs" :count="count" @update:model-value="tab=$event; page=1" />
   </div>
   <div v-if="!rows.length" class="biz-empty"><h3>暂无符合条件的订单</h3><p>{{ showEmpty ? '当前为演示空状态' : productScope ? '该商品暂无符合条件的订单，可调整筛选或查看全部订单。' : '调整筛选条件或查看其他状态。' }}</p><ElButton v-if="showEmpty" @click="showEmpty=false">返回列表</ElButton><ElButton v-else @click="reset">清空筛选</ElButton><ElButton v-if="productScope" @click="clearProductScope">查看全部订单</ElButton><ElButton type="primary" plain @click="fillDemo">演示填入</ElButton></div>
   <div v-else class="table-wrap order-list"><table><colgroup><col style="width:16%"/><col style="width:23%"/><col style="width:23%"/><col style="width:12%"/><col style="width:10%"/><col style="width:16%"/></colgroup><thead><tr><th>订单 / 下单时间</th><th>商品信息</th><th>来源园区 / 收货人</th><th>实付金额</th><th>订单状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td><button class="link" @click="openDetails(o)">{{ o.id }}</button><small>{{ o.created }}</small></td><td><OrderProductSummary :items="o.items" /></td><td>{{ o.park }}<small>{{ o.receiver || '未记录收货人' }}<template v-if="o.phone"> · {{ o.phone }}</template></small></td><td><strong>{{ paidText(o) }}</strong></td><td><ElTag size="small" :type="o.status==='completed'||o.status==='received'?'success':o.status==='cancelled'?'info':'warning'">{{ isPartial(o) ? '部分发货' : labels[o.status] }}</ElTag></td><td><ElButton v-if="o.status==='pending_ship'" text type="primary" @click="openShipping(o)">去发货</ElButton><ElButton text @click="openDetails(o)">详情</ElButton></td></tr></tbody></table></div><ListPagination v-model:page="page" :page-size="20" :total="matched.length" noun="笔订单" />
  </template>
  <template v-else-if="order">
   <header class="detail-heading detail-header">
    <ElButton text @click="backToList"><ArrowLeft :size="16" />返回订单管理</ElButton><h1>订单详情</h1><span class="detail-header-id">订单号：{{ order.id }}</span><ElButton text type="primary" @click="copyText(order.id)">复制</ElButton><div class="detail-top-actions"><ElButton @click="contactOpen=true">联系买家</ElButton><ElButton v-if="order.status==='pending_ship'" type="primary" @click="openShipping(order)">去发货</ElButton></div>
   </header>
   <section class="detail-progress" aria-label="订单进度">
    <div v-for="(name,index) in ['支付','发货','签收','完成']" :key="name" class="detail-progress-step" :class="{ done:order.status!=='cancelled' && (index < stage(order) || order.status==='completed'), current:order.status!=='cancelled' && order.status!=='completed' && index===stage(order) }">
      <span class="detail-progress-dot">{{ order.status!=='cancelled' && (index < stage(order) || order.status==='completed') ? '✓' : index+1 }}</span><strong>{{ name }}</strong><i v-if="index<3" />
    </div>
    <span v-if="order.status==='cancelled'" class="detail-cancelled">订单已取消</span>
   </section>
   <div class="detail-layout">
    <main class="detail-main">
     <section class="detail-panel detail-products-panel">
      <div class="detail-section-head"><h2>商品信息</h2><ElTag size="small" :type="order.status==='completed'||order.status==='received'?'success':order.status==='cancelled'?'info':'warning'">{{ isPartial(order) ? '部分发货' : labels[order.status] }}</ElTag></div>
      <div class="detail-notice" :class="{'detail-notice-warning':order.status==='pending_pay'||order.status==='pending_ship'}">{{ order.status==='pending_pay'?'等待客户支付':order.status==='pending_ship'?(isPartial(order)?'部分发货，请按下方各商品的待发数量继续发货':'待发货，请按下方各商品的待发数量安排发货'):order.status==='shipped'?'已发货，等待客户确认收货':order.status==='received'?'已签收，签收满 7 天后进入完成（状态由后台处理）':order.status==='completed'?'订单已完成':'订单已取消' }}</div>
      <div class="detail-product-table"><table><colgroup><col style="width:32%"/><col style="width:14%"/><col style="width:10%"/><col style="width:14%"/><col style="width:14%"/><col style="width:16%"/></colgroup><thead><tr><th>商品</th><th>单价</th><th>数量</th><th>已发 / 待发</th><th>小计</th><th>备注</th></tr></thead><tbody>
       <tr v-for="i in order.items" :key="i.id"><td><div class="detail-product"><div class="detail-product-image"><DemoImage :source="i.cover" empty-text="暂无图片" /></div><div class="detail-product-copy"><button v-if="linkedProduct(i)" class="link detail-product-name" @click="openProduct(i)">{{ i.name }}</button><strong v-else>{{ i.name }}</strong><small>订货编码 {{ i.orderCode || '—' }} · 供应商 SKU {{ i.sku || '—' }}<template v-if="i.brand"> · 品牌 {{ i.brand }}</template><template v-if="i.model"> · 型号 {{ i.model }}</template></small></div></div></td><td>{{ money(i.price) }} / {{ i.unit }}</td><td>{{ i.qty }} {{ i.unit }}</td><td>{{ i.shipped }} / {{ i.qty-i.shipped }} {{ i.unit }}</td><td><strong>{{ money(i.price*i.qty) }}</strong></td><td>{{ i.remark || '—' }}</td></tr>
      </tbody></table></div>
     </section>
     <section class="detail-panel"><div class="detail-section-head"><h2>收货信息</h2><ElButton size="small" @click="copyText([order.receiver,order.phone,order.address].filter(Boolean).join('\n'))"><Copy :size="14"/>复制收货信息</ElButton></div><dl class="detail-receiver"><div><dt>收货人</dt><dd>{{ order.receiver || '未记录收货人' }}</dd></div><div><dt>联系电话</dt><dd>{{ order.phone || '—' }}</dd></div><div class="detail-receiver-wide"><dt>收货地址</dt><dd>{{ order.address || '—' }}</dd></div><div class="detail-receiver-wide"><dt>买家留言</dt><dd>{{ order.buyerNote || '—' }}</dd></div></dl></section>
     <section class="detail-panel"><div class="detail-section-head"><h2>发货信息</h2></div><p v-if="!order.shipments.length" class="detail-empty">暂无发货记录</p><div v-for="(s,index) in order.shipments" :key="index" class="detail-shipment"><div class="detail-shipment-head"><strong>{{ s.company }}<span v-if="s.tracking"> · {{ s.tracking }}</span></strong><div class="shipment-actions"><ElButton size="small" @click="shipmentIndex=index">查看发货详情</ElButton><ElButton v-if="s.tracking" size="small" @click="copyText(`${s.company} ${s.tracking}`)"><Copy :size="14"/>复制物流信息</ElButton></div></div><small>{{ s.time }}</small><p>{{ s.lines.map(l => { const item=order!.items.find(i=>i.id===l.itemId); return `${item?.name || '商品'} × ${l.qty} ${item?.unit || ''}` }).join('、') }}</p><small v-if="s.note">备注：{{ s.note }}</small></div></section>
    </main>
    <aside class="detail-aside">
     <section class="detail-panel detail-price"><h2>价格详情</h2><dl class="detail-facts"><div><dt>商品合计</dt><dd>{{ money(amount(order)) }}</dd></div><div><dt>运费</dt><dd>{{ order.freight ? money(order.freight) : '免运费' }}</dd></div><div class="detail-paid"><dt>实付款</dt><dd>{{ paidText(order) }}</dd></div></dl></section>
     <section class="detail-panel"><h2>订单信息</h2><dl class="detail-facts"><div><dt>订单号</dt><dd>{{ order.id }}</dd></div><div><dt>来源园区</dt><dd>{{ order.park }}</dd></div><div><dt>客户</dt><dd>{{ order.customer || '—' }}</dd></div><div><dt>商品种类</dt><dd>{{ order.items.length }} 种</dd></div><div><dt>商品数量</dt><dd>{{ quantityByUnit(order) }}</dd></div><div><dt>履约状态</dt><dd>{{ isPartial(order) ? '已发货（部分发货）' : labels[order.status] }}</dd></div><div><dt>下单时间</dt><dd>{{ order.created }}</dd></div><div><dt>支付截止</dt><dd>{{ order.payDueAt || '—' }}</dd></div><div><dt>支付时间</dt><dd>{{ order.paidAt || '—' }}</dd></div><div><dt>发货时间</dt><dd>{{ order.shipments.length ? order.shipments[order.shipments.length-1]?.time : '—' }}</dd></div><div v-if="order.autoReceiveAt"><dt>预计自动签收</dt><dd>{{ order.autoReceiveAt }}</dd></div><div><dt>签收时间</dt><dd>{{ order.receivedAt || '—' }}</dd></div><div><dt>完成时间</dt><dd>{{ order.completedAt || '—' }}</dd></div><div v-if="order.status==='cancelled' && order.cancelledAt"><dt>取消时间</dt><dd>{{ order.cancelledAt }}</dd></div></dl></section>
     <section v-if="order.status==='received'||order.status==='completed'" class="detail-panel"><h2>结算信息</h2><dl class="detail-facts"><div><dt>结算状态</dt><dd>{{ order.settleStatus || '待结算' }}</dd></div><div><dt>结算时间</dt><dd>{{ order.settledAt || '—' }}</dd></div><div><dt>平台佣金率</dt><dd>{{ order.commissionRate == null ? '—' : `${order.commissionRate}%` }}</dd></div><div><dt>应结金额</dt><dd>{{ order.settleAmount == null ? '—' : money(order.settleAmount) }}</dd></div></dl></section>
     <div v-if="order.status==='pending_pay'||order.status==='shipped'" class="detail-demo"><span>演示操作</span><ElButton size="small" @click="simulate(order)">{{ order.status==='pending_pay'?'模拟客户支付':'模拟确认收货' }}</ElButton></div>
    </aside>
   </div>
  </template>
  <section v-else class="biz-empty"><h3>未找到该订单</h3><p>订单可能已删除或不属于当前供应商。</p><ElButton @click="backToList">返回订单管理</ElButton></section>
  <ElDialog v-model="contactOpen" title="联系买家" width="400px" append-to-body><template v-if="order"><p>收货人：{{order.receiver || '未记录收货人'}}</p><p>联系电话：{{order.phone || '暂无联系电话'}}</p></template><template #footer><ElButton @click="contactOpen=false">关闭</ElButton></template></ElDialog>
  <ElDialog v-model="shipping" title="填写发货信息" width="600px" append-to-body><template v-if="shippingOrder"><div class="ship-demo"><p class="muted">填写本次发货数量，可分批发货。</p><ElButton size="small" @click="fillShipping">演示填入</ElButton></div><ElCheckboxGroup v-model="shipSelected"><div v-for="i in shippingOrder.items" :key="i.id" class="ship-item"><ElCheckbox :value="i.id" :disabled="i.qty<=i.shipped"><strong>{{ i.name }}</strong><small>{{ i.sku }} · 待发 {{ i.qty-i.shipped }} {{ i.unit }}</small></ElCheckbox><ElInputNumber v-model="shipForm.quantities[i.id]" :min="0" :max="i.qty-i.shipped" :precision="0" :disabled="!shipSelected.includes(i.id)" /></div></ElCheckboxGroup><div class="ship-fields"><label><span>配送方式</span><ElSelect v-model="shipForm.self"><ElOption label="物流配送" :value="false" /><ElOption label="自有车辆配送（自送）" :value="true" /></ElSelect></label><label v-if="!shipForm.self"><span>物流公司 *</span><ElSelect v-model="shipForm.company" filterable allow-create default-first-option placeholder="选择或输入物流公司"><ElOption v-for="company in ['顺丰速运','京东物流','中通快递','圆通速递','韵达快递','申通快递','德邦快递']" :key="company" :label="company" :value="company" /></ElSelect></label><label v-if="!shipForm.self"><span>物流单号 *</span><ElInput v-model="shipForm.tracking" placeholder="填写物流单号" /></label><label><span>{{ shipForm.self ? '自送说明 *' : '备注' }}</span><ElInput v-model="shipForm.note" :placeholder="shipForm.self ? '填写自送说明' : '选填'" /></label></div></template><template #footer><ElButton @click="shipping=false">取消</ElButton><ElButton type="primary" @click="submitShipping">确认发货</ElButton></template></ElDialog>
  <ElDialog :model-value="shipmentIndex!==null" title="发货详情" width="560px" append-to-body @close="shipmentIndex=null"><template v-if="selectedShipment && order"><dl class="shipment-detail-facts"><div><dt>配送方式</dt><dd>{{selectedShipment.company==='自送'?'自送':'物流配送'}}</dd></div><div><dt>物流公司</dt><dd>{{selectedShipment.company}}</dd></div><div><dt>物流单号</dt><dd>{{selectedShipment.tracking||'—'}}</dd></div><div><dt>发货时间</dt><dd>{{selectedShipment.time}}</dd></div></dl><h3 class="shipment-detail-title">本次发货商品</h3><div v-for="line in selectedShipment.lines" :key="line.itemId" class="shipment-detail-line"><span>{{order.items.find(i=>i.id===line.itemId)?.name||'商品'}}</span><strong>{{line.qty}} {{order.items.find(i=>i.id===line.itemId)?.unit||''}}</strong></div><p v-if="selectedShipment.note" class="muted">备注：{{selectedShipment.note}}</p></template><template #footer><ElButton v-if="selectedShipment?.tracking" @click="copyText(`${selectedShipment.company} ${selectedShipment.tracking}`)">复制物流信息</ElButton><ElButton type="primary" @click="shipmentIndex=null">关闭</ElButton></template></ElDialog>
 </div>
</template>
